+*{box-sizing:border-box}
+html{color-scheme:dark}
+body{
+  margin:0;
+  background:
+    radial-gradient(1200px 600px at 20% -10%, rgba(230,57,70,.22), transparent 60%),
+    radial-gradient(900px 500px at 90% 10%, rgba(255,0,0,.15), transparent 55%),
+    linear-gradient(180deg, #0c0c0d, var(--bg));
+  color:var(--text);
+  font-family:var(--font-body);
+  line-height:1.5;
+}
+
+a{color:inherit;text-decoration:none}
+a:hover{text-decoration:underline}
+
+.container{max-width:var(--max);margin:0 auto;padding:0 20px}
+.stack{display:flex;flex-direction:column;gap:18px}
+
+.skip-link{
+  position:absolute;left:-999px;top:auto;width:1px;height:1px;overflow:hidden;
+}
+.skip-link:focus{
+  left:16px;top:16px;width:auto;height:auto;z-index:9999;
+  background:#000;border:1px solid var(--line);padding:10px 12px;border-radius:10px;
+}
+
+/* Top promo */
+.topbar{
+  background:rgba(20,20,22,.75);
+  border-bottom:1px solid var(--line);
+  backdrop-filter: blur(10px);
+}
+.topbar-inner{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:10px 0}
+.topbar p{margin:0;color:var(--muted);font-size:14px}
+
+/* Nav */
+.nav{
+  position:sticky;top:0;z-index:50;
+  background:rgba(15,15,16,.82);
+  border-bottom:1px solid var(--line);
+  backdrop-filter: blur(10px);
+}
+.nav-inner{height:var(--nav-h);display:flex;align-items:center;justify-content:space-between;gap:14px}
+.brand{display:flex;align-items:center;gap:12px;min-width:180px}
+.brand-mark{
+  width:34px;height:34px;border-radius:10px;
+  background:radial-gradient(circle at 30% 20%, #ff6b6b, var(--accent) 55%, rgba(255,0,0,.50));
+  box-shadow:0 18px 40px rgba(230,57,70,.25);
+}
+.brand-name{font-family:var(--font-head);letter-spacing:.08em;text-transform:uppercase;font-size:22px;line-height:1}
+.brand-sub{display:block;color:var(--muted-2);font-size:12px;margin-top:2px}
+
+.nav-links{display:flex;align-items:center;gap:18px}
+.nav-links a{color:var(--muted);font-weight:600;font-size:14px;letter-spacing:.02em}
+.nav-links a[aria-current="page"]{color:var(--text)}
+.nav-links a:hover{color:var(--text);text-decoration:none}
+
+.nav-cta{display:flex;align-items:center;gap:10px}
+.btn{
+  display:inline-flex;align-items:center;justify-content:center;
+  gap:10px;padding:12px 16px;border-radius:14px;
+  border:1px solid var(--line);
+  background:rgba(255,255,255,.04);
+  color:var(--text);
+  font-weight:800;letter-spacing:.03em;text-transform:uppercase;
+  cursor:pointer;
+}
+.btn:hover{background:rgba(255,255,255,.07);text-decoration:none}
+.btn:focus-visible{outline:2px solid rgba(230,57,70,.9);outline-offset:2px}
+
+.btn-primary{
+  border-color:rgba(230,57,70,.55);
+  background:linear-gradient(180deg, rgba(230,57,70,.96), rgba(180,14,29,.96));
+  box-shadow:0 18px 55px rgba(230,57,70,.20);
+}
+.btn-primary:hover{filter:saturate(1.05) brightness(1.02)}
+
+.btn-ghost{background:transparent}
+.pill{
+  display:inline-flex;align-items:center;gap:10px;
+  padding:8px 12px;border-radius:999px;
+  border:1px solid var(--line);
+  color:var(--muted);
+  background:rgba(255,255,255,.03);
+  font-size:13px;font-weight:650;
+}
+
+.menu-btn{display:none}
+
+/* Hero */
+.hero{
+  padding:46px 0 34px;
+}
+.hero-grid{display:grid;grid-template-columns:1.1fr .9fr;gap:24px;align-items:stretch}
+.hero-card{
+  position:relative;
+  border:1px solid var(--line);
+  background:linear-gradient(180deg, rgba(20,20,22,.72), rgba(15,15,16,.65));
+  border-radius:var(--radius);
+  overflow:hidden;
+  box-shadow:var(--shadow-soft);
+}
+.hero-copy{padding:34px}
+.kicker{color:var(--muted);font-weight:700;font-size:13px;letter-spacing:.18em;text-transform:uppercase}
+h1,h2,h3{font-family:var(--font-head);text-transform:uppercase;letter-spacing:.06em;margin:0}
+h1{font-size:56px;line-height:.92;margin-top:10px}
+p{margin:0;color:var(--muted)}
+.hero-copy p{max-width:56ch;margin-top:14px;font-size:16px}
+
+.hero-actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:20px}
+
+.hero-metrics{display:flex;gap:10px;flex-wrap:wrap;margin-top:22px}
+.metric{padding:10px 12px;border-radius:14px;border:1px solid var(--line);background:rgba(255,255,255,.03)}
+.metric strong{display:block;color:var(--text);letter-spacing:.02em}
+.metric span{display:block;color:var(--muted-2);font-size:12px;margin-top:2px}
+
+/* Carousel */
+.carousel{height:100%;display:flex;flex-direction:column}
+.carousel-stage{position:relative;flex:1;min-height:360px}
+.carousel-track{
+  display:flex;
+  height:100%;
+  transition:transform 520ms cubic-bezier(.2,.9,.2,1);
+  will-change:transform;
+}
+.slide{
+  width:100%;flex:0 0 100%;
+  display:flex;align-items:flex-end;
+  background:
+    radial-gradient(700px 300px at 30% 10%, rgba(230,57,70,.32), transparent 60%),
+    linear-gradient(135deg, rgba(255,255,255,.05), rgba(255,255,255,.00));
+  position:relative;
+}
+.slide::before{
+  content:"";
+  position:absolute;inset:0;
+  background:
+    radial-gradient(900px 500px at 80% 40%, rgba(0,0,0,.40), rgba(0,0,0,.76));
+}
+.slide-inner{position:relative;padding:26px}
+.slide-inner h3{font-size:32px}
+.slide-inner p{margin-top:8px;max-width:44ch}
+
+.carousel-controls{
+  position:absolute;inset:auto 18px 18px 18px;
+  display:flex;align-items:center;justify-content:space-between;gap:12px;
+}
+.icon-btn{
+  width:44px;height:44px;border-radius:14px;
+  border:1px solid var(--line);
+  background:rgba(0,0,0,.35);
+  color:var(--text);
+  display:inline-flex;align-items:center;justify-content:center;
+  cursor:pointer;
+}
+.icon-btn:hover{background:rgba(0,0,0,.55)}
+
+.dots{display:flex;gap:8px;align-items:center;justify-content:center}
+.dot{width:10px;height:10px;border-radius:999px;border:1px solid var(--line);background:rgba(255,255,255,.08);cursor:pointer}
+.dot[aria-current="true"]{background:var(--accent);border-color:rgba(230,57,70,.55)}
+
+/* Sections */
+.section{padding:44px 0}
+.section-title{display:flex;align-items:flex-end;justify-content:space-between;gap:18px;margin-bottom:18px}
+.section-title h2{font-size:40px}
+.section-title p{max-width:70ch}
+
+.grid-2{display:grid;grid-template-columns:1fr 1fr;gap:18px}
+.card{
+  border:1px solid var(--line);
+  background:rgba(20,20,22,.60);
+  border-radius:var(--radius);
+  padding:22px;
+  box-shadow:var(--shadow-soft);
+}
+.card h3{font-size:28px}
+.card p{margin-top:10px}
+.card .btn{margin-top:14px}
+
+.two-ways .card{position:relative;overflow:hidden}
+.two-ways .card::after{
+  content:"";position:absolute;right:-80px;top:-80px;width:200px;height:200px;
+  background:radial-gradient(circle at 30% 30%, rgba(230,57,70,.38), transparent 60%);
+  transform:rotate(18deg);
+}
+
+.split{
+  display:grid;grid-template-columns:1fr .95fr;gap:18px;align-items:stretch;
+}
+.media{
+  border:1px solid var(--line);
+  border-radius:var(--radius);
+  background:
+    radial-gradient(900px 600px at 40% 10%, rgba(230,57,70,.22), transparent 60%),
+    linear-gradient(135deg, rgba(255,255,255,.06), rgba(255,255,255,.01));
+  min-height:320px;
+  position:relative;
+  overflow:hidden;
+}
+.media::before{
+  content:"";
+  position:absolute;inset:0;
+  background:
+    linear-gradient(180deg, rgba(0,0,0,.15), rgba(0,0,0,.70));
+}
+.media .stamp{position:absolute;left:18px;top:18px}
+.media .stamp strong{display:block;font-family:var(--font-head);letter-spacing:.08em;text-transform:uppercase;font-size:28px}
+.media .stamp span{display:block;color:var(--muted);margin-top:6px;max-width:34ch}
+
+/* Dominant CTA */
+.cta-dominant{
+  background:radial-gradient(1200px 450px at 30% 20%, rgba(230,57,70,.28), transparent 62%),
+             linear-gradient(180deg, rgba(20,20,22,.80), rgba(10,10,11,.90));
+  border-top:1px solid var(--line);
+  border-bottom:1px solid var(--line);
+}
+.cta-panel{
+  border:1px solid rgba(230,57,70,.25);
+  background:linear-gradient(180deg, rgba(230,57,70,.12), rgba(0,0,0,.15));
+  border-radius:28px;
+  padding:28px;
+  display:flex;align-items:center;justify-content:space-between;gap:18px;
+  box-shadow:0 30px 90px rgba(230,57,70,.16);
+}
+.cta-panel h2{font-size:44px}
+.cta-panel p{margin-top:10px;max-width:68ch}
+.cta-panel .btn{padding:14px 18px}
+
+/* Workout toggle */
+.toggle{
+  display:inline-flex;border:1px solid var(--line);border-radius:999px;overflow:hidden;
+  background:rgba(255,255,255,.03);
+}
+.toggle button{
+  border:0;background:transparent;color:var(--muted);
+  padding:10px 14px;font-weight:800;letter-spacing:.04em;text-transform:uppercase;
+  cursor:pointer;min-width:140px;
+}
+.toggle button[aria-pressed="true"]{background:rgba(230,57,70,.18);color:var(--text)}
+.toggle button:focus-visible{outline:2px solid rgba(230,57,70,.9);outline-offset:-2px}
+
+.toggle-panel{border:1px solid var(--line);border-radius:var(--radius);padding:22px;background:rgba(20,20,22,.60)}
+.toggle-panel[hidden]{display:none}
+
+/* Table */
+table{width:100%;border-collapse:separate;border-spacing:0;overflow:hidden;border-radius:var(--radius)}
+th,td{padding:14px 14px;border-bottom:1px solid var(--line);text-align:left}
+th{color:var(--text);background:rgba(255,255,255,.03);font-size:13px;letter-spacing:.14em;text-transform:uppercase}
+tr:last-child td{border-bottom:0}
+td{color:var(--muted)}
+.table-wrap{border:1px solid var(--line);border-radius:var(--radius);overflow:hidden;background:rgba(20,20,22,.60)}
+.table-note{margin-top:10px;color:var(--muted-2);font-size:13px}
+
+/* Instructors */
+.filters{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}
+.select{
+  display:flex;align-items:center;gap:10px;
+  padding:10px 12px;border-radius:14px;border:1px solid var(--line);
+  background:rgba(255,255,255,.03);
+}
+select{
+  background:transparent;border:0;color:var(--text);
+  font-weight:700;font-size:14px;appearance:none;
+}
+select:focus-visible{outline:2px solid rgba(230,57,70,.9);outline-offset:2px}
+
+.grid{
+  display:grid;
+  grid-template-columns:repeat(4,1fr);
+  gap:14px;
+}
+.instructor{
+  border:1px solid var(--line);
+  border-radius:var(--radius);
+  background:rgba(20,20,22,.60);
+  padding:16px;
+  transition:transform 220ms ease, opacity 220ms ease;
+}
+.instructor.is-hidden{opacity:0;transform:scale(.98);pointer-events:none;display:none}
+.avatar{
+  width:100%;aspect-ratio:4/3;border-radius:14px;
+  background:
+    radial-gradient(450px 240px at 30% 20%, rgba(230,57,70,.30), transparent 60%),
+    linear-gradient(135deg, rgba(255,255,255,.06), rgba(255,255,255,.01));
+  border:1px solid rgba(255,255,255,.08);
+}
+.instructor h3{font-size:22px;margin-top:12px}
+.instructor .meta{margin-top:6px;color:var(--muted-2);font-size:13px}
+.instructor a{display:inline-flex;margin-top:12px;font-weight:800;text-transform:uppercase;letter-spacing:.05em;color:rgba(230,57,70,.95)}
+
+.empty{
+  border:1px dashed rgba(255,255,255,.18);
+  border-radius:var(--radius);
+  padding:18px;
+  color:var(--muted);
+  background:rgba(0,0,0,.20);
+}
+
+/* Accordion */
+.accordion{border:1px solid var(--line);border-radius:var(--radius);overflow:hidden;background:rgba(20,20,22,.60)}
+.acc-item + .acc-item{border-top:1px solid var(--line)}
+.acc-btn{
+  width:100%;text-align:left;
+  padding:16px 16px;
+  display:flex;align-items:center;justify-content:space-between;gap:12px;
+  border:0;background:transparent;color:var(--text);
+  cursor:pointer;
+}
+.acc-btn span{font-family:var(--font-head);letter-spacing:.06em;text-transform:uppercase;font-size:22px}
+.acc-btn:focus-visible{outline:2px solid rgba(230,57,70,.9);outline-offset:-2px}
+.acc-panel{padding:0 16px 16px;color:var(--muted)}
+.acc-panel[hidden]{display:none}
+
+/* Newsletter */
+.newsletter{
+  border:1px solid var(--line);
+  border-radius:var(--radius);
+  background:rgba(20,20,22,.60);
+  padding:18px;
+}
+.newsletter form{display:flex;gap:10px;flex-wrap:wrap;align-items:flex-start}
+.field{flex:1;min-width:220px}
+input[type="email"]{
+  width:100%;padding:12px 12px;border-radius:14px;
+  border:1px solid var(--line);
+  background:rgba(0,0,0,.35);
+  color:var(--text);
+}
+input[type="email"]:focus-visible{outline:2px solid rgba(230,57,70,.9);outline-offset:2px}
+.help{margin-top:8px;font-size:13px;color:var(--muted-2)}
+.help.is-bad{color:var(--bad)}
+.help.is-good{color:var(--good)}
+
+/* Footer */
+footer{padding:34px 0;border-top:1px solid var(--line);background:rgba(10,10,11,.65)}
+.footer-grid{display:grid;grid-template-columns:1.2fr .8fr .8fr;gap:16px;align-items:start}
+.footer-grid h3{font-size:24px}
+.footer-grid a{color:var(--muted);font-weight:650;font-size:14px}
+.footer-grid a:hover{color:var(--text);text-decoration:none}
+.footer-note{margin-top:12px;color:var(--muted-2);font-size:13px}
+
+.country{
+  position:relative;
+}
+.country button{width:100%;justify-content:space-between}
+.country-menu{
+  position:absolute;right:0;top:calc(100% + 10px);
+  width:min(320px, 90vw);
+  border:1px solid var(--line);
+  border-radius:16px;
+  background:rgba(10,10,11,.92);
+  box-shadow:var(--shadow);
+  padding:10px;
+}
+.country-menu[hidden]{display:none}
+.country-menu button{
+  width:100%;
+  padding:10px 12px;
+  border-radius:12px;
+  background:transparent;
+  border:1px solid transparent;
+  color:var(--muted);
+  text-align:left;
+  cursor:pointer;
+}
+.country-menu button:hover{border-color:rgba(255,255,255,.12);background:rgba(255,255,255,.04);color:var(--text)}
+
+/* Mobile */
+@media (max-width: 980px){
+  h1{font-size:46px}
+  .hero-grid{grid-template-columns:1fr;}
+  .carousel-stage{min-height:320px}
+  .split{grid-template-columns:1fr}
+  .grid{grid-template-columns:repeat(2,1fr)}
+  .footer-grid{grid-template-columns:1fr;}
+}
+
+@media (max-width: 720px){
+  :root{--nav-h:68px}
+  .nav-links{display:none}
+  .menu-btn{display:inline-flex}
+  h1{font-size:40px}
+  .hero-copy{padding:24px}
+  .section-title{flex-direction:column;align-items:flex-start}
+  .grid-2{grid-template-columns:1fr}
+  .cta-panel{flex-direction:column;align-items:flex-start}
+  .grid{grid-template-columns:1fr}
+}
+
+@media (prefers-reduced-motion: reduce){
+  .carousel-track{transition:none}
+  .instructor{transition:none}
+}
+
*** End Patch
PATCH

